    if (live || !from || !to || to !== todayIso()) return 0;
    const a = new Date(`${from}T12:00:00`);
    const b = new Date(`${to}T12:00:00`);
    if (Number.isNaN(a.getTime()) || Number.isNaN(b.getTime())) return 0;
