function normalizeOrderPayments() {
  if (!Array.isArray(state.orders)) return;
  for (const o of state.orders) {
    if (!o.paymentTerm) o.paymentTerm = "cash";
    if (o.paymentTerm === "cash") o.isPaid = true;
    else if (o.paymentTerm === "credit") {
      o.isPaid = !!o.isPaid;
      // Credit never keeps cash % discount — clear stale flags from cash→credit edits.
      if (o.applyPercentDiscount) {
        o.applyPercentDiscount = false;
        o.percentDiscount = 0;
        recalcOrderTotals(o);
      }
    }
  }
}
function normalizeOrderDeliveryDates() {
  if (!Array.isArray(state.orders)) return;
  for (const o of state.orders) {
    const created = orderTakenDay(o) || isoDay(o.createdAt);
    const stored = isoDay(o.deliveryDate);
    if (!stored) {
      o.deliveryDate = defaultDeliveryDate(created) || tomorrowIso();
      continue;
    }
    // Older saves incorrectly set deliveryDate to the order day.
    if (created && stored === created) {
      o.deliveryDate = defaultDeliveryDate(created);
    }
  }
}
function normalizeOrderTakenDays() {
  if (!Array.isArray(state.orders)) return;
  for (const o of state.orders) {
    const locked = normalizeIsoDateInput(o.takenDay);
    if (locked) {
      o.takenDay = locked;
      continue;
    }
    const fromCreated = isoDay(o.createdAt);
    if (fromCreated) o.takenDay = fromCreated;
  }
}
function normalizeOrderTotals() {
  if (!Array.isArray(state.orders)) return;
  for (const o of state.orders) {
    const itemsChanged = normalizeOrderItemPrices(o);
    const liveGross = orderGrossFromItems(o);
    const cachedGross = o.grossTotal != null ? Number(o.grossTotal) : null;
    if (
      itemsChanged ||
      !Number.isFinite(Number(o.total)) ||
      (cachedGross != null && Math.abs(cachedGross - liveGross) > 0.01)
    ) {
      recalcOrderTotals(o);
    }
  }
}
function normalizeOrderReceiptNumbers() {
  if (!Array.isArray(state.orders)) return;
  const sorted = [...state.orders].sort(
    (a, b) => new Date(a.createdAt) - new Date(b.createdAt),
  );
  const maxByMonth = {};
  const usedByMonth = {};
  const claimed = new Map();

  for (const o of sorted) {
    const month = receiptMonthKey(o);
    if (!month) continue;
    o.receiptMonth = month;
    if (!usedByMonth[month]) usedByMonth[month] = new Set();
    const seq = Number(o.receiptSeq);
    if (seq > 0 && !usedByMonth[month].has(seq)) {
      usedByMonth[month].add(seq);
      claimed.set(o.id, seq);
      maxByMonth[month] = Math.max(maxByMonth[month] || 0, seq);
    }
  }

  for (const o of sorted) {
    const month = receiptMonthKey(o);
    if (!month) continue;
    if (claimed.has(o.id)) {
      o.receiptSeq = claimed.get(o.id);
      continue;
    }
    maxByMonth[month] = (maxByMonth[month] || 0) + 1;
    o.receiptSeq = maxByMonth[month];
    if (!usedByMonth[month]) usedByMonth[month] = new Set();
    usedByMonth[month].add(o.receiptSeq);
  }
}
function nextOrderId() {
  let max = 0;
  for (const o of state.orders || []) {
    const raw = String(o?.id || "");
    const n = Number(raw);
    if (Number.isFinite(n) && n > max) max = n;
  }
  for (const entry of state.deletionLog || []) {
    if (entry?.type !== "order") continue;
    const n = Number(entry.id);
    if (Number.isFinite(n) && n > max) max = n;
  }
  let next = max + 1;
  while (
    (state.orders || []).some((o) => String(o?.id) === String(next)) ||
    deletionLogHas(state.deletionLog || [], "order", String(next))
  ) {
    next += 1;
  }
  return String(next);
}
function buildNewOrder(fields) {
  const createdAt = fields.createdAt || new Date().toISOString();
  const takenDay =
    normalizeIsoDateInput(fields.takenDay) ||
    isoDay(createdAt) ||
    todayIso();
  const receiptMonth = receiptMonthKey({ createdAt, takenDay });
  const created = takenDay;
  const stored = isoDay(fields.deliveryDate);
  const deliveryDate =
    stored && !(created && stored === created)
      ? stored
      : defaultDeliveryDate(created) || tomorrowIso();
  return {
    id: nextOrderId(),
    receiptMonth,
    receiptSeq: nextReceiptSeq(receiptMonth),
    ...fields,
    createdAt,
    takenDay,
    deliveryDate,
  };
}
