function qtyDraft(el) {
  const id = el.getAttribute("data-product-id") || "";
  const p = state.products.find((x) => x.id === id);
  if (!p) return;
  const min = Number(el.closest(".qty-stepper")?.dataset?.qtyMin ?? 0);
  const digits = String(el.value || "").replace(/\D/g, "");
  if (digits !== el.value) el.value = digits;
  if (!digits) return;
  const n = Number(digits);
  const maxOk = maxWorkerPaidQty(id);
  if (n > maxOk) showStockLimitToast(`${p.name}: урамшуулалтай нийт үлдэгдлээс хэтэрнэ`);
  const capped = Math.min(n, maxOk);
  if (capped < min) return;
  state.workerQty[id] = capped;
  if (String(capped) !== digits) el.value = String(capped);
  el.setAttribute("aria-valuenow", String(capped));
  if (pickerOpen()) {
    if (el.hasAttribute("data-picker-qty-input")) syncPickerQtySheetUi(id);
    else updatePickerClearBtn();
  }
}
function qtyCommit(el) {
  const id = el.getAttribute("data-product-id") || "";
  const p = state.products.find((x) => x.id === id);
  if (!p) return;
  const min = Number(el.closest(".qty-stepper")?.dataset?.qtyMin ?? 0);
  const digits = String(el.value || "").replace(/\D/g, "");
  let v = digits ? Number(digits) : 0;
  const maxOk = maxWorkerPaidQty(id);
  if (v > maxOk) showStockLimitToast(`${p.name}: урамшуулалтай нийт үлдэгдлээс хэтэрнэ`);
  if (v < min) v = min;
  v = Math.min(v, maxOk);
  el.value = String(v);
  el.setAttribute("aria-valuenow", String(v));
  setWorkerQty(id, v);
}
function initQtyStepperButtons() {
  if (document.documentElement.dataset.qtyStepperBound) return;
  document.documentElement.dataset.qtyStepperBound = "1";
  document.addEventListener(
    "pointerdown",
    (e) => {
      const packKinds = [
        ["data-picker-large-action", "large"],
        ["data-picker-pack-action", "pack"],
        ["data-picker-piece-action", "piece"],
      ];
      for (const [attr, kind] of packKinds) {
        const packBtn = e.target.closest?.(`[${attr}]`);
        if (!packBtn) continue;
        e.preventDefault();
        e.stopPropagation();
        if (packBtn.disabled && packBtn.getAttribute(attr) === "inc") {
          showStockLimitToast();
        } else if (!packBtn.disabled) {
          pickerPartStepperApply(packBtn, kind);
        }
        return;
      }
      const btn = e.target.closest?.(".qty-stepper__btn[data-qty-action]");
      if (!btn) return;
      if (btn.disabled) {
        if (
          btn.getAttribute("data-qty-action") === "inc" &&
          btn.closest("[data-picker-root]")
        ) {
          showStockLimitToast();
        }
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      qtyStepperApply(btn);
    },
    true,
  );
}
