function percentDiscountSettingsModal() {
  if (!canManagePercentDiscountSettings()) return;
  ensureSettings();
  const rate = percentDiscountRate();
  box(
    "Шууд төлөлтийн хувь оруулах",
    `<form onsubmit="savePercentDiscountSettings(event)" class="p-5 space-y-4"><p class="text-sm text-muted-foreground">(Харилцагч хүлээн авсан барааны төлбөрийг шууд төлөх үед хөнгөлөлтийн хэмжээ)</p><label class="block text-sm font-medium">Шууд төлөлтийн хувь (%)</label><input name="percentDiscountRate" type="tel" inputmode="decimal" autocomplete="off" min="0" max="100" step="0.1" required value="${rate}" class="w-full px-3 py-3 bg-secondary rounded app-input"><div class="grid grid-cols-2 gap-2 pt-1"><button type="button" onclick="closeModal()" class="py-2.5 bg-secondary rounded font-medium text-sm">Буцах</button><button type="submit" class="py-2.5 bg-primary text-primary-foreground rounded font-medium text-sm">Хадгалах</button></div></form>`,
    "max-w-md",
  );
}
function savePercentDiscountSettings(e) {
  if (!isAdmin()) return;
  e.preventDefault();
  ensureSettings();
  const raw = Number(new FormData(e.target).get("percentDiscountRate"));
  state.settings.percentDiscountRate = Math.min(
    100,
    Math.max(0, Number.isFinite(raw) ? raw : RECEIPT_PERCENT_DISCOUNT),
  );
  if (!canApplyPercentDiscount()) state.applyPercentDiscount = false;
  closeModal();
  render();
  showInstallToast("Шууд төлөлтийн хувь хадгалагдлаа");
  criticalBackendSave();
}
function orderRetentionSettingsModal() {
  if (!canManageOrderHistorySettings()) return;
  ensureSettings();
  const days = orderRetentionDays();
  box(
    "Захиалгын түүх хадгалах",
    `<form onsubmit="saveOrderRetentionSettings(event)" class="p-5 space-y-4"><p class="text-sm text-muted-foreground">Захиалгын түүхэнд тохируулсан хугацааны дотор системээс автоматаар устана. <b>Авлагатай (төлөөгүй) баримт хэзээ ч устахгүй.</b></p><label class="block text-sm font-medium">Хадгалах хоног</label><input name="orderRetentionDays" type="tel" inputmode="numeric" pattern="[0-9]*" autocomplete="off" min="7" max="365" required value="${days}" class="w-full px-3 py-3 bg-secondary rounded app-input"><div class="grid grid-cols-2 gap-2 pt-1"><button type="button" onclick="closeModal()" class="py-2.5 bg-secondary rounded font-medium text-sm">Буцах</button><button type="submit" class="py-2.5 bg-primary text-primary-foreground rounded font-medium text-sm">Хадгалах</button></div></form>`,
    "max-w-md",
  );
}
function saveOrderRetentionSettings(e) {
  if (!isAdmin()) return;
  e.preventDefault();
  ensureSettings();
  const raw = Number(new FormData(e.target).get("orderRetentionDays"));
  state.settings.orderRetentionDays = Math.min(
    365,
    Math.max(7, Number.isFinite(raw) ? Math.floor(raw) : 31),
  );
  closeModal();
  render();
  showInstallToast("Захиалгын түүх хадгалах хугацаа шинэчлэгдлээ");
  criticalBackendSave();
}
function deletionLogLabel(entry) {
  if (!entry) return { type: "-", actor: "-" };
  const type =
    entry.type === "product"
      ? "Бараа"
      : entry.type === "customer"
        ? "Харилцагч"
        : entry.type === "employee"
          ? "Ажилтан"
          : entry.type === "order"
            ? "Баримт / захиалга"
            : String(entry.type || "-");
  const actor =
    state.employees.find((e) => e.id === entry.actorId)?.name ||
    entry.actorId ||
    "-";
  return { type, actor };
}
