let receiptExcelLogoDataUri = "";
async function getReceiptExcelLogoDataUri() {
  if (
    receiptExcelLogoDataUri &&
    /^data:image\//i.test(receiptExcelLogoDataUri)
  ) {
    return receiptExcelLogoDataUri;
  }
  try {
    const res = await fetch(staticAssetUrl(BRAND.receiptLogo), {
      cache: "no-store",
    });
    if (!res.ok) throw new Error("logo missing");
    const blob = await res.blob();
    receiptExcelLogoDataUri = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const result = String(reader.result || "");
        if (!/^data:image\//i.test(result)) {
          reject(new Error("logo not data uri"));
          return;
        }
        resolve(result);
      };
      reader.onerror = () => reject(new Error("logo read failed"));
      reader.readAsDataURL(blob);
    });
    return receiptExcelLogoDataUri;
  } catch {
    // Bundled logo — never leave the receipt header blank.
    receiptExcelLogoDataUri = RECEIPT_LOGO_DATA_URI;
    return RECEIPT_LOGO_DATA_URI;
  }
}
function buildReceiptExcelDocument(orders, logoSrc) {
  const pages = orders
    .map((o) => receiptExcelPage(orderReceiptSnapshot(o), logoSrc))
    .join("");
  return `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta http-equiv="Content-Type" content="text/html; charset=utf-8">
<!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Баримт</x:Name><x:WorksheetOptions><x:Print><x:ValidPrinterInfo/><x:PaperSizeIndex>9</x:PaperSizeIndex></x:Print></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->
<style>${RECEIPT_EXCEL_STYLES}</style>
</head>
<body>${pages}</body>
</html>`;
}
function receiptExcelFileName(orders) {
  const stamp = new Date().toISOString().slice(0, 10);
  if (orders.length === 1) {
    const no = String(formatReceiptNumber(orders[0]) || "1").replace(
      /[^\w.-]+/gu,
      "-",
    );
    return `Зарлагын баримт - ${no}.xlsx`;
  }
  return `Зарлагын баримт - ${stamp}.xlsx`;
}
function receiptHtmlFileName(orders) {
  return receiptExcelFileName(orders).replace(/\.xlsx$/i, ".html");
}
function legacyExcelFileName(name) {
  return safeDownloadFileName(
    String(name || "excel.xlsx").replace(/\.(xlsx|xls|csv)$/i, ".xls"),
    "application/vnd.ms-excel",
  );
}
async function downloadReceiptExcelBlob(name, html) {
  // Same print HTML + CSS as on-screen preview so download matches what you see.
  const fileName = String(name || "Зарлагын баримт.html").replace(
    /\.(xlsx|xls|zip)$/i,
    ".html",
  );
  const blob = new Blob(["\uFEFF" + html], {
    type: "application/octet-stream",
  });
  return downloadBlobFile(blob, fileName, {
    skipShare: !prefersMobileExcelShare(),
    savePicker: !prefersMobileExcelShare(),
  });
}
function exportOrderReceiptsExcelCsv(orders) {
  const stamp = new Date().toISOString().slice(0, 10),
    sheetRows = [
      ["ТОМУДА — Захиалгын баримтууд"],
      [`Тайлан огноо: ${dte(new Date())}`],
      [`Баримтын тоо: ${orders.length}`],
      [],
    ];
  orders.forEach((o, idx) => {
    if (idx > 0) sheetRows.push([], ["--------------------"], []);
    sheetRows.push(...buildOrderReceiptExcelRows(o));
  });
  excel(`Захиалгын-баримт-${stamp}.xlsx`, sheetRows);
}
const RECEIPT_XLSX_LAST_COL = "K";
/** Canonical ҮНДСЭН layout (BIFF). Runtime Excel mirrors this sample. */
const RECEIPT_XLSX_SOURCE_TEMPLATE =
  "/static/tomuda/templates/zarlaga-receipt-undsen.xls";
const RECEIPT_XLSX_TEMPLATE = RECEIPT_XLSX_SOURCE_TEMPLATE;
/** No top pad — sample starts at R1. */
const RECEIPT_XLSX_TOP_PAD_ROWS = 0;
// ҮНДСЭН A–K: E wide enough for full «Хэмжих нэгж» on one line (fitToWidth).
// Take from B/C so the header never clips.
const RECEIPT_XLSX_COL_WIDTHS = [
  3.0, 12.5, 6.5, 3.875, 15.25, 9.625, 5.625, 4.875, 3.75, 9.25, 9.5,
];
/** Approximate Excel column-width units for a 9pt Arial label. */
function receiptXlsxLabelUnits(text) {
  let units = 0;
  for (const ch of String(text ?? "")) {
    if (ch === " " || ch === "\u00A0") units += 0.5;
    else if (ch === ":") units += 0.55;
    else if (/[\u0400-\u04FF]/.test(ch)) units += 1.12;
    else units += 0.95;
  }
  return units;
}
/** Word-aware wrap line count — matches Excel better than raw char ceil. */
function receiptXlsxWrapLineCount(text, charsPerLine) {
  const limit = Math.max(6, Number(charsPerLine) || 12);
  let total = 0;
  for (const part of String(text ?? "").split(/\r?\n/)) {
    const words = part.trim() ? part.trim().split(/\s+/) : [""];
    let cur = 0;
    let lines = 1;
    for (const word of words) {
      const wlen = [...word].length || 1;
      if (cur === 0) {
        if (wlen <= limit) {
          cur = wlen;
        } else {
          const full = Math.ceil(wlen / limit);
          lines += full - 1;
          cur = wlen % limit || limit;
        }
        continue;
      }
      if (cur + 1 + wlen <= limit) {
        cur += 1 + wlen;
        continue;
      }
      lines += 1;
      if (wlen <= limit) {
        cur = wlen;
      } else {
        const full = Math.ceil(wlen / limit);
        lines += full - 1;
        cur = wlen % limit || limit;
      }
    }
    total += lines;
  }
  return Math.max(1, total);
}
/** Compact single-line rows; multi-line only as tall as needed for full text. */
function receiptXlsxWrappedRowHeight(
  text,
  colWidth = 18,
  { min = 14, linePt = 12, pad = 2, max = 52 } = {},
) {
  const raw = String(text ?? "").trim() || "-";
  // Numbers/Excel fit more Arial-9 glyphs than raw customWidth units.
  // Keep mid-length names (…/Гүзээлзгэнэ/) on one line — too-low limit made empty 2-line rows.
  const charsPerLine = Math.max(
    10,
    Math.round((Number(colWidth) || 18) * 1.35),
  );
  const lines = receiptXlsxWrapLineCount(raw, charsPerLine);
  if (lines <= 1) return min;
  return Math.max(min, Math.min(max, lines * linePt + pad));
}
function receiptXlsxColsXml() {
  return RECEIPT_XLSX_COL_WIDTHS.map(
    (width, index) =>
      `<col min="${index + 1}" max="${index + 1}" width="${width}" customWidth="1"/>`,
  ).join("");
}
function excelSerialFromDate(value) {
  const d = value ? new Date(value) : new Date();
  if (Number.isNaN(d.getTime())) return excelSerialFromDate(new Date());
  return (
    (Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) -
      Date.UTC(1899, 11, 30)) /
    86400000
  );
}
