function customerExcel() {
  if (!canExportExcel()) return;
  if (!state.customers.length) return alert("Харилцагч байхгүй");
  const sorted = [...state.customers].sort((a, b) =>
    String(a.name || "").localeCompare(String(b.name || ""), "mn"),
  );
  const phoneCount = Math.max(
    2,
    ...sorted.map((c) => customerPhonesList(c).length),
  );
  const phoneHeaders = Array.from(
    { length: phoneCount },
    (_, i) => `Утас ${i + 1}`,
  );
  const rows = [
    [
      "№",
      "Нэр",
      "РД",
      "Байгууллагын нэр",
      ...phoneHeaders,
      "И-мэйл",
      "Аймаг/Хот",
      "Дүүрэг/Сум",
      "Хороо",
      "Дэлгэрэнгүй хаяг",
      "Уртраг",
      "Өргөрөг",
    ],
    ...sorted.map((c, i) => {
      const phones = customerPhonesList(c);
      const lat = c.latitude ?? "";
      const lng = c.longitude ?? "";
      return [
        i + 1,
        c.name || "",
        c.registrationNumber || "",
        c.companyName || "",
        ...Array.from({ length: phoneCount }, (_, n) => phones[n] || ""),
        c.email || "",
        c.province || "",
        c.district || "",
        c.khoroo || "",
        c.address || "",
        lng === "" || lng === null || lng === undefined ? "" : String(lng),
        lat === "" || lat === null || lat === undefined ? "" : String(lat),
      ];
    }),
  ];
  // Minimum widths so name/company/address are fully readable (not clipped).
  const colMins = [
    5,
    20,
    12,
    24,
    ...phoneHeaders.map(() => 12),
    24,
    14,
    14,
    12,
    40,
    12,
    12,
  ];
  excel("Харилцагч.xlsx", rows, {
    sheetName: "Харилцагч",
    colMins,
    maxColWidth: 56,
  });
}
function customerAddress(c) {
  return (
    [c.province, c.district, c.khoroo, c.address].filter(Boolean).join(", ") ||
    "-"
  );
}
/** Store label for delivery / maps — never blank if companyName exists. */
function customerDisplayName(c) {
  return (
    String(c?.name || "").trim() ||
    String(c?.companyName || "").trim() ||
    "Дэлгүүр"
  );
}
function customerLookupMap() {
  const byId = new Map();
  for (const c of state.customers || []) {
    if (c?.id == null) continue;
    const id = String(c.id);
    byId.set(id, c);
    const bare = id.replace(/^c-/i, "");
    if (bare) {
      if (!byId.has(bare)) byId.set(bare, c);
      if (!byId.has(`c-${bare}`)) byId.set(`c-${bare}`, c);
    }
  }
  return byId;
}
function findCustomerForOrder(o, byId = null) {
  const map = byId || customerLookupMap();
  const customerId = String(o?.customerId || "").trim();
  if (customerId) {
    const hit =
      map.get(customerId) ||
      map.get(customerId.replace(/^c-/i, "")) ||
      map.get(`c-${customerId.replace(/^c-/i, "")}`);
    if (hit) return hit;
  }
  return null;
}
/** Prefer live customer name so renamed stores show on older orders. */
function orderCustomerName(o) {
  const c = findCustomerForOrder(o);
  if (c) {
    const live = customerDisplayName(c);
    if (live && live !== "Дэлгүүр") return live;
    if (live) return live;
  }
  const snap =
    String(o?.customerName || "").trim() ||
    String(o?.companyName || "").trim();
  return snap || "Харилцагч";
}
function syncOrdersCustomerName(customer) {
  if (!customer?.id) return 0;
  const name = customerDisplayName(customer);
  if (!name || name === "Дэлгүүр") return 0;
  const map = customerLookupMap();
  // Also match orders that point at this customer via id aliases.
  const aliases = new Set([String(customer.id)]);
  const bare = String(customer.id).replace(/^c-/i, "");
  if (bare) {
    aliases.add(bare);
    aliases.add(`c-${bare}`);
  }
  let changed = 0;
  for (const o of state.orders || []) {
    const oid = String(o.customerId || "").trim();
    if (!aliases.has(oid) && findCustomerForOrder(o, map) !== customer) {
      continue;
    }
    if (String(o.customerName || "").trim() === name) continue;
    o.customerName = name;
    if (!oid) o.customerId = customer.id;
    changed += 1;
  }
  return changed;
}
let orderCustomerNameHealQueued = false;
/** Backfill blank order.customerName from the live customer record. */
function healOrderCustomerNames() {
  const map = customerLookupMap();
  let changed = 0;
  for (const o of state.orders || []) {
    const c = findCustomerForOrder(o, map);
    if (!c) continue;
    const name = customerDisplayName(c);
    if (!name || name === "Дэлгүүр") continue;
    if (String(o.customerName || "").trim() === name) continue;
    o.customerName = name;
    changed += 1;
  }
  if (changed && !orderCustomerNameHealQueued) {
    orderCustomerNameHealQueued = true;
    queueMicrotask(() => {
      orderCustomerNameHealQueued = false;
      persistOrderSnapshot();
      scheduleBackendSave();
    });
  }
  return changed;
}
