function stockOutModal(id) {
  ensureStockOutSession();
  if (!canManageStockOut()) {
    return alertModal("Эрхгүй", "Зарлага бүртгэх эрхгүй.");
  }
  const p = state.products.find((x) => x.id === id);
  if (!p) return;
  const d = state.stockOutDraft[p.id] || {};
  box(
    "Зарлага гаргах",
    stockTakeEntryFormHtml(p, d, "out"),
    "max-w-md stock-in-take-modal",
  );
  requestAnimationFrame(() => {
    const form = modal.querySelector("form.stock-in-take");
    const large = form?.querySelector('input[name="largePacks"]');
    if (large && String(large.value || "").trim()) {
      stockInLargePacksInput(large);
    }
  });
}
function applyStockOutModal(e, id) {
  e.preventDefault();
  ensureStockOutSession();
  if (!canManageStockOut()) {
    return alertModal("Эрхгүй", "Зарлага бүртгэх эрхгүй.");
  }
  if (!state.stockOutEmployeeId) return alert("Ажилтан сонгоно уу");
  const p = state.products.find((x) => x.id === id);
  if (!p) return;
  const formData = new FormData(e.target);
  const largePacks = Math.max(
    0,
    Math.floor(Number(formData.get("largePacks") || 0)),
  );
  const packs = Math.max(0, Math.floor(Number(formData.get("packs") || 0)));
  const pieces = Math.max(0, Math.floor(Number(formData.get("qty") || 0)));
  const qty = stockInEntryTotalQty(largePacks, packs, pieces, p);
  if (qty <= 0) {
    delete state.stockOutDraft[id];
    state.stockOutDone = false;
    state.stockOutReceipt = null;
    closeModal();
    render();
    return;
  }
  const stockNow = Number(p.stock) || 0;
  if (qty > stockNow) {
    alert("Үлдэгдэл хүрэлцэхгүй байна!");
    return;
  }
  const entry = stockOutDraftEntry(id);
  const smallSize = productPackSize(p);
  const largePieces = productLargeBoxPieceCount(p);
  if (largePieces && largePacks > 0) entry.largePacks = String(largePacks);
  else delete entry.largePacks;
  if (smallSize && packs > 0) entry.packs = String(packs);
  else delete entry.packs;
  if (pieces > 0) entry.qty = String(pieces);
  else delete entry.qty;
  if (!smallSize && !largePieces) {
    entry.qty = String(pieces);
    delete entry.packs;
    delete entry.largePacks;
  }
  const note = String(formData.get("note") || "").trim();
  if (note) entry.note = note;
  else delete entry.note;
  state.stockOutDone = false;
  state.stockOutReceipt = null;
  state.stockOutHighlightId = id;
  closeModal();
  render();
  showAppToast(`${p.name} · −${qty} ш нэмэгдлээ`, "success");
}
function exportStockOutExcel(receipt) {
  if (!receipt?.lines?.length) return alert("Зарлагын баримт байхгүй");
  return exportStockOutExcelXlsx(receipt)
    .then(() => showInstallToast("Мэдээлэл татагдлаа"))
    .catch((err) => {
      console.warn("Stock-out xlsx failed", err);
      try {
        exportStockOutExcelFallback(receipt);
        showInstallToast("Мэдээлэл татагдлаа");
      } catch (fallbackErr) {
        console.warn("Stock-out excel fallback failed", fallbackErr);
        alert("Мэдээлэл татахад алдаа гарлаа. Дахин оролдоно уу.");
      }
    });
}
